update market_wallet_action
set wallet_txn_id = #{walletTxnId, jdbcType=BINARY},
    update_time = current_timestamp
where action_id = #{lease.actionId, jdbcType=BINARY}
  and status = 'PROCESSING'
  and lease_token = #{lease.token, jdbcType=BINARY}
  and processing_lease_until > #{leaseValidAt}
  and (wallet_txn_id is null or wallet_txn_id = #{walletTxnId, jdbcType=BINARY})

update market_wallet_action
set status = 'PROCESSING',
    next_retry_at = null,
    processing_lease_until = #{claim.leaseUntil},
    lease_token = #{claim.lease.token, jdbcType=BINARY},
    update_time = current_timestamp
where action_id = #{claim.lease.actionId, jdbcType=BINARY}
  and status = #{claim.expectedStatus}
  and retry_count = #{claim.expectedRetryCount}
  and retry_count < #{claim.maxRetryAttempts}
  and (next_retry_at is null or next_retry_at <= #{claim.claimedAt})

update market_wallet_action
set status = case
        when retry_count >= (#{maxRetryAttempts} - 1) then 'DEAD'
        else 'RETRYING'
    end,
    next_retry_at = case
        when retry_count >= (#{maxRetryAttempts} - 1) then null
        else #{nextRetryAt}
    end,
    retry_count = case
        when retry_count >= (#{maxRetryAttempts} - 1) then retry_count
        else retry_count + 1
    end,
    last_error = #{lastError},
    processing_lease_until = null,
    lease_token = null,
    update_time = current_timestamp
where action_id = #{actionId, jdbcType=BINARY}
  and status = 'FAILED'
  and failure_code = #{expectedFailureCode}
  and retry_count = #{expectedRetryCount}
  and wallet_txn_id is null

update market_wallet_action
set status = case
        when retry_count >= (#{recovery.maxRetryAttempts} - 1) then 'DEAD'
        else 'RETRYING'
    end,
    next_retry_at = case
        when retry_count >= (#{recovery.maxRetryAttempts} - 1) then null
        else #{recovery.nextRetryAt}
    end,
    retry_count = case
        when retry_count >= (#{recovery.maxRetryAttempts} - 1) then retry_count
        else retry_count + 1
    end,
    last_error = #{recovery.lastError},
    processing_lease_until = null,
    lease_token = null,
    update_time = current_timestamp
where action_id = #{recovery.actionId, jdbcType=BINARY}
  and status = 'PROCESSING'
  and retry_count = #{recovery.expectedRetryCount}
  and processing_lease_until = #{recovery.expectedLeaseUntil}
  and processing_lease_until <= #{recovery.asOf}


          and lease_token = #{recovery.expectedLeaseToken, jdbcType=BINARY}


          and lease_token is null

update market_wallet_action
set retry_count = retry_count + 1,
    next_retry_at = #{nextRetryAt},
    last_error = #{lastError},
    update_time = current_timestamp
where action_id = #{actionId, jdbcType=BINARY}
  and status = #{expectedStatus}
  and status not in ('SUCCEEDED', 'PROCESSING')
  and wallet_txn_id = #{walletTxnId, jdbcType=BINARY}

update market_wallet_action
set next_retry_at = #{nextRetryAt},
    last_error = #{lastError},
    update_time = current_timestamp
where action_id = #{actionId, jdbcType=BINARY}
  and status = #{expectedStatus}
  and status = 'FAILED'
  and failure_code = #{expectedFailureCode}
  and wallet_txn_id is null
